-- BF2 award catalog: every medal, ribbon and badge with its requirements.
-- Award ids are the standard BF2 ids and double as icon file names
-- (public/images/awards/<id>.png, badges as <id>_<level>.png).
-- Requirement text follows the public BF2Hub player profile page.
-- IAR = "in a round", meaning one single game.
--
-- Run after 010_profiles.sql. Safe to re-run.

on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  stages = excluded.stages,
  sort_order = excluded.sort_order;
